package fu.se184491.loadmaster_be.service.vehicle;

import org.junit.jupiter.api.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import fu.se184491.loadmaster_be.security.TestJwtSupport;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** Real PG/JDBC/JPA transactions and HTTP security, entirely synthetic tenant fixtures. */
class VehicleTransferPostgresTest extends VehiclePresencePostgresTest {
 VehicleTransferService transfers(){return ctx.getBean(VehicleTransferService.class);}
 void as(long id){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(Long.toString(id),null));}
 long requested(){as(11);return ((Number)transfers().request(1,101,102,"Synthetic reposition",UUID.randomUUID()).get("id")).longValue();}
 void destinationWorker(){sql.update("INSERT INTO warehouse_staff_assignments VALUES(10,1,102,true) ON CONFLICT DO NOTHING");as(10);}
 @Test void requestedDoesNotMoveButReservesVehicle(){long id=requested();assertTrue(id>0);assertEquals("AT_WAREHOUSE",store.presence(1,1).status());assertEquals(101L,store.presence(1,1).warehouseId());assertFalse(store.eligibleIds(1,101,null,0,100).contains(1L));assertThrows(RuntimeException.class,()->tx.execute(t->eligibility.requireLocked(1,101L,1,null)));}
 @Test void fullJourneyIsPhysicalAtomicAndIdempotent(){long id=requested();var departure=UUID.randomUUID();as(7);transfers().confirm(101,id,false,departure);transfers().confirm(101,id,false,departure);assertEquals("IN_TRANSIT",store.presence(1,1).status());assertNull(store.presence(1,1).warehouseId());destinationWorker();var arrival=UUID.randomUUID();transfers().confirm(102,id,true,arrival);transfers().confirm(102,id,true,arrival);assertEquals("AT_WAREHOUSE",store.presence(1,1).status());assertEquals(102L,store.presence(1,1).warehouseId());assertEquals(3,store.events(1,1).size());assertTrue(store.eligibleIds(1,102,null,0,100).contains(1L));as(7);transfers().confirm(101,id,false,departure);assertEquals(102L,store.presence(1,1).warehouseId());assertEquals(3,store.events(1,1).size());}
 @Test void regularCheckinCannotBypassRequestedOrTransit(){long id=requested();as(7);assertThrows(RuntimeException.class,()->service.checkIn(101,1,UUID.randomUUID()));transfers().confirm(101,id,false,UUID.randomUUID());destinationWorker();assertThrows(RuntimeException.class,()->service.checkIn(102,1,UUID.randomUUID()));}
 @Test void cancelOnlyBeforeDepartureAndPreservesPresence(){long id=requested();transfers().cancel(id);transfers().cancel(id);assertEquals(101L,store.presence(1,1).warehouseId());assertEquals(1,store.events(1,1).size());assertTrue(store.eligibleIds(1,101,null,0,100).contains(1L));long next=requested();as(7);transfers().confirm(101,next,false,UUID.randomUUID());as(11);assertThrows(RuntimeException.class,()->transfers().cancel(next));}
 @Test void workerCannotActAtOtherWarehouseOrTenant(){long id=requested();as(7);assertThrows(RuntimeException.class,()->transfers().confirm(102,id,true,UUID.randomUUID()));as(9);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));assertEquals("REQUESTED",ctx.getBean(VehicleTransferStore.class).find(id,1,false).get("status"));}
 @Test void unavailableUnknownWrongSourceAndSameWarehouseRejected(){as(11);assertThrows(RuntimeException.class,()->transfers().request(6,101,102,"x",UUID.randomUUID()));assertThrows(RuntimeException.class,()->transfers().request(4,101,102,"x",UUID.randomUUID()));assertThrows(RuntimeException.class,()->transfers().request(1,102,101,"x",UUID.randomUUID()));assertThrows(RuntimeException.class,()->transfers().request(1,101,101,"x",UUID.randomUUID()));assertThrows(RuntimeException.class,()->transfers().request(1,101,201,"x",UUID.randomUUID()));}
 @Test void loadingAndInTransitTripsBlockRequest(){as(11);for(String status:List.of("LOADING","IN_TRANSIT")){sql.update("INSERT INTO trips(company_id,vehicle_id,status) VALUES(1,1,?)",status);assertThrows(RuntimeException.class,()->transfers().request(1,101,102,"x",UUID.randomUUID()));sql.update("DELETE FROM trips");}}
 @Test void draftsKeptButCannotStartDuringTransfer(){sql.update("INSERT INTO trips(id,company_id,vehicle_id,status) VALUES(90,1,1,'DRAFT')");requested();assertEquals("DRAFT",sql.queryForObject("SELECT status FROM trips WHERE id=90",String.class));assertThrows(RuntimeException.class,()->tx.executeWithoutResult(t->service.departure(departing(),8)));}
 @Test void duplicateRequestAndPayloadConflict(){as(11);var key=UUID.randomUUID();var first=transfers().request(1,101,102,"x",key);assertEquals(first.get("id"),transfers().request(1,101,102,"x",key).get("id"));assertThrows(RuntimeException.class,()->transfers().request(2,101,102,"x",key));assertThrows(RuntimeException.class,()->transfers().request(1,101,102,"different",key));assertThrows(RuntimeException.class,()->transfers().request(1,101,102,"x",UUID.randomUUID()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM vehicle_warehouse_transfers",Integer.class));}
 @Test void revokeBlocksUncommittedConfirmation(){long id=requested();sql.update("UPDATE warehouse_staff_assignments SET active=false WHERE user_id=7");as(7);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));assertEquals("AT_WAREHOUSE",store.presence(1,1).status());}
 @Test void failedAuditRollsBackPresenceEventAndTransfer(){long id=requested();sql.execute("ALTER TABLE audit_logs ADD CONSTRAINT reject_transfer_test CHECK(action_type<>'VEHICLE_TRANSFER') NOT VALID");try{as(7);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));assertEquals("AT_WAREHOUSE",store.presence(1,1).status());assertEquals(1,store.events(1,1).size());assertEquals("REQUESTED",ctx.getBean(VehicleTransferStore.class).find(id,1,false).get("status"));}finally{sql.execute("ALTER TABLE audit_logs DROP CONSTRAINT reject_transfer_test");}}
 @Test void concurrentRequestsOnlyOneActive()throws Exception{var result=race(()->{as(11);transfers().request(1,101,102,"x",UUID.randomUUID());return true;},()->{as(11);transfers().request(1,101,102,"x",UUID.randomUUID());return true;});assertEquals(1,result.stream().filter(Boolean::booleanValue).count());}
 @Test void concurrentDuplicateDepartureOneEvent()throws Exception{long id=requested();var key=UUID.randomUUID();var result=race(()->{as(7);transfers().confirm(101,id,false,key);return true;},()->{as(7);transfers().confirm(101,id,false,key);return true;});assertEquals(List.of(true,true),result);assertEquals(2,store.events(1,1).size());}
 @Test void concurrentAdmissionAndRequestNeverBothWin()throws Exception{var result=race(()->{as(11);transfers().request(1,101,102,"x",UUID.randomUUID());return true;},()->tx.execute(t->{eligibility.requireLocked(1,101L,1,null);sql.update("INSERT INTO trips(company_id,vehicle_id,status) VALUES(1,1,'LOADING')");return true;}));assertEquals(1,result.stream().filter(Boolean::booleanValue).count());}
 @Test void changedPresenceOrTripRejectsDeparture(){long id=requested();sql.update("INSERT INTO trips(company_id,vehicle_id,status) VALUES(1,1,'LOADING')");as(7);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));}
 @Test void arrivalCannotPrecedeDeparture(){long id=requested();destinationWorker();assertThrows(RuntimeException.class,()->transfers().confirm(102,id,true,UUID.randomUUID()));}
 @Test void maintenanceArrivalRecordedButNotEligible(){long id=requested();as(7);transfers().confirm(101,id,false,UUID.randomUUID());sql.update("UPDATE vehicles SET status='MAINTENANCE' WHERE id=1");destinationWorker();transfers().confirm(102,id,true,UUID.randomUUID());assertEquals(102L,store.presence(1,1).warehouseId());assertFalse(store.eligibleIds(1,102,null,0,100).contains(1L));}
 @Test void httpRolesAndTenantAndAssignment()throws Exception{String path="/api/vehicle-transfers";http.perform(get(path)).andExpect(status().isUnauthorized());http.perform(get(path).header("Authorization",worker("7"))).andExpect(status().isForbidden());http.perform(post(path).header("Authorization","Bearer "+TestJwtSupport.userToken("11","DISPATCHER")).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"vehicleId\":1,\"sourceWarehouseId\":101,\"destinationWarehouseId\":102,\"reason\":\"test\"}")).andExpect(status().isOk());long id=sql.queryForObject("SELECT id FROM vehicle_warehouse_transfers",Long.class);http.perform(post("/api/warehouse/vehicle-presence/101/transfers/"+id+"/departure").header("Authorization",worker("9")).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isNotFound());http.perform(get("/api/warehouse/vehicle-presence/102/transfers").header("Authorization",worker("7"))).andExpect(status().isForbidden());}

 @Test void databaseRejectsDuplicateTenantMismatchAndLateTransitions(){long id=requested();assertThrows(RuntimeException.class,()->sql.update("INSERT INTO vehicle_warehouse_transfers(company_id,vehicle_id,source_warehouse_id,destination_warehouse_id,requested_by,request_key,reason) VALUES(1,1,101,102,11,?,'x')",UUID.randomUUID()));assertThrows(RuntimeException.class,()->sql.update("INSERT INTO vehicle_warehouse_transfers(company_id,vehicle_id,source_warehouse_id,destination_warehouse_id,requested_by,request_key,reason) VALUES(1,2,101,201,11,?,'x')",UUID.randomUUID()));assertThrows(RuntimeException.class,()->sql.update("UPDATE vehicle_warehouse_transfers SET source_warehouse_id=102 WHERE id=?",id));transfers().cancel(id);assertThrows(RuntimeException.class,()->sql.update("UPDATE vehicle_warehouse_transfers SET status='REQUESTED',version=version+1,cancelled_by=null,cancelled_at=null WHERE id=?",id));}
 @Test void concurrentArrivalRetriesOneCheckin()throws Exception{long id=requested();as(7);transfers().confirm(101,id,false,UUID.randomUUID());destinationWorker();var key=UUID.randomUUID();var result=race(()->{as(10);transfers().confirm(102,id,true,key);return true;},()->{as(10);transfers().confirm(102,id,true,key);return true;});assertEquals(List.of(true,true),result);assertEquals(3,store.events(1,1).size());}
 @Test void revokeHoldingAssignmentMakesWaitingDepartureFail()throws Exception{long id=requested();var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var locked=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);try{var revoke=pool.submit(()->tx.execute(t->{sql.update("UPDATE warehouse_staff_assignments SET active=false WHERE user_id=7 AND warehouse_id=101");locked.countDown();try{release.await(10,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}return true;}));assertTrue(locked.await(10,java.util.concurrent.TimeUnit.SECONDS));var depart=pool.submit(()->{as(7);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));return true;});assertThrows(java.util.concurrent.TimeoutException.class,()->depart.get(500,java.util.concurrent.TimeUnit.MILLISECONDS));release.countDown();assertTrue(revoke.get(15,java.util.concurrent.TimeUnit.SECONDS));assertTrue(depart.get(15,java.util.concurrent.TimeUnit.SECONDS));assertEquals("AT_WAREHOUSE",store.presence(1,1).status());}finally{release.countDown();pool.shutdownNow();}}
 @Test void inactiveStaffCannotConfirmEvenWithStalePrincipal(){long id=requested();sql.update("UPDATE users SET status='INACTIVE' WHERE id=7");as(7);assertThrows(RuntimeException.class,()->transfers().confirm(101,id,false,UUID.randomUUID()));}
 @Test void oldRegularReceiptDoesNotBypassActiveTransfer(){as(7);var key=UUID.randomUUID();service.checkIn(101,1,key);requested();as(7);assertThrows(RuntimeException.class,()->service.checkIn(101,1,key));}
 @Test void physicalCatalogueFilterKeepsCorrectServerTotal(){as(7);var page=service.vehicles(101,"",0,1,true);assertEquals(3,page.getTotalElements());assertEquals(1,page.getContent().size());assertEquals(1L,((Number)page.getContent().getFirst().get("id")).longValue());}
 @Test void dispatcherListNeverLeaksOtherTenant()throws Exception{requested();sql.update("INSERT INTO users VALUES(15,2,'Dispatcher B','DISPATCHER','ACTIVE')");http.perform(get("/api/vehicle-transfers").header("Authorization","Bearer "+TestJwtSupport.userToken("15","DISPATCHER"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.length()").value(0));as(15);assertThrows(RuntimeException.class,()->transfers().cancel(1));}
 @Test void keyCannotBeReboundToAnotherTransfer(){long first=requested();as(11);long second=((Number)transfers().request(2,101,102,"x",UUID.randomUUID()).get("id")).longValue();as(7);var key=UUID.randomUUID();transfers().confirm(101,first,false,key);assertThrows(RuntimeException.class,()->transfers().confirm(101,second,false,key));assertEquals("AT_WAREHOUSE",store.presence(2,1).status());}
 @Test void schemaHasRlsAndNoBrowserRoleGrants(){assertTrue(sql.queryForObject("SELECT relrowsecurity FROM pg_class WHERE oid='vehicle_warehouse_transfers'::regclass",Boolean.class));for(String role:List.of("anon","authenticated"))for(String permission:List.of("SELECT","INSERT","UPDATE","DELETE","TRUNCATE"))assertFalse(sql.queryForObject("SELECT has_table_privilege(?, 'vehicle_warehouse_transfers', ?)",Boolean.class,role,permission));}
}
